import { useState } from 'react';
import Display from './Display';

export default function App({ initial = '', options = [] as string[] }: { initial?: string; options?: string[] }) {
  const [selected, setSelected] = useState(initial);
  // BUG : Display reçoit une valeur figée au lieu de l'état remonté.
  return (
    <div>
      <Display value="?" />
      {options.map((o) => (
        <button className="opt" key={o} onClick={() => setSelected(o)}>{o}</button>
      ))}
    </div>
  );
}

export default function Display({ value }: { value: string }) {
  return <p id="display">Choix : {value}</p>;
}

